\begin{claim}{A1.1}{Proved}{Local freeness and the determinant line}
Both $\mathcal A$ and $\mathcal E$ are locally free, of ranks three and
two.  The vertical vector $\xi=\partial/\partial\zeta_2$ is nowhere
zero as a section of $\mathcal E^\vee$.  There is an exact sequence
of holomorphic vector bundles
\begin{equation}\label{eq:A-E-line}
0\longrightarrow N\longrightarrow\mathcal E
 \xrightarrow{\langle\cdot,\xi\rangle}\OO_X\longrightarrow0,
\qquad N=\det\mathcal E=\omega_f(-2S_1-3S_2).
\end{equation}
\end{claim}

\begin{claim}{A1.2}{Proved}{The logarithmic direct images by vertical twisting and duality}
One has, as holomorphic vector bundles on $B$,
\[
\begin{array}{c|ccc}
q&0&1&2\\\hline
R^qf_*\mathcal E&\OO\oplus\OO(-1)&
 \OO^2\oplus\OO(-1)^2&\OO\oplus\OO(-1).
\end{array}
\]
They commute with base change to every full scheme fibre.
\end{claim}

\begin{claim}{A1.3}{Proved}{All absolute cotangent direct images}
For every admissible $c$, the six direct images are
\begin{equation}\label{eq:A-absolute-table}
\begin{array}{c|cc}
q&R^qf_*\Omega_X^1&R^qf_*\Omega_X^2\\\hline
0&\OO(-2)&\OO(-2)\oplus\OO(-1)\\
1&\OO\oplus\OO(-1)^2&\OO(-2)\oplus\OO(-1)^2\\
2&\OO\oplus\OO(-1)&\OO.
\end{array}
\end{equation}
In particular every listed sheaf is torsion-free.
\end{claim}

\begin{claim}{A2.1}{Proved}{The complete raw period determinant}
On the marked upper half-plane,
\begin{equation}\label{eq:A-modular-K}
6\mu_z^2-\tau_z\beta_z
=\tau_z^2\frac{E_4(\tau)^2}{E_6(\tau)}.
\end{equation}
The right side extends holomorphically through the apparent poles.
Its exact orders are two at $z_1$ and zero at $z_2$; it has no other
zero away from their translates.  The logarithmic connecting map
$\kappa_0:f_*\mathcal E\to\mathcal L\otimes G$ has divisor
$\operatorname{divisor}(\det\kappa_0)=p_1+p_2$.
\end{claim}

\begin{claim}{A2.3}{Proved}{Identification of the elliptic logarithm and the verified zero formula}
For the Weierstrass equation
\[
y^2=x^3-3t^3(t-1)x+2t^4(t-1)^2,
\]
the section $[\mu]$ is a generator of its rational section group and
equals one of $P_*=(0,\sqrt2t^2(t-1))$ and $-P_*$.
In particular $\wp(\mu,\tau)=0$ on every regular fibre.
Along the branch in \eqref{eq:A-s-branch}, with
$x_0=1-1/t$, the exact branch is
\begin{equation}\label{eq:A-DI-branch}
\mu=\frac{1-\tau}{2}
 +\frac{i\sqrt6}{3\pi}
 \frac{x_0^{1/4}\,{}_3F_2(1/3,2/3,1;3/4,5/4;x_0)}
 {{}_2F_1(1/12,5/12;1;1-x_0)}.
\end{equation}
Consequently $\mu-(2-\tau)/3$ has exact order two at the
order-three point in $r^3=t$.
\end{claim}

\begin{claim}{A3.1}{Proved}{The complete Hodge table for every admissible parameter}
For every $\operatorname{Im}c<-M$, the Hodge numbers are
\[
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&1&2&1\\
1&1&2&1&0\\
0&1&0&0&0.
\end{array}
\]
\end{claim}

\begin{claim}{A4.2}{Refuted}{The claimed degree-one torsion along the cusp}
The assertion in AC26 Remark 9.21, PDF page 81, that
$\Omega_{X/B}^1$ has torsion along $W\cup S_1\cup S_2$ is false.
Its torsion is supported precisely on $S_1\cup S_2$; its degree-one
cusp modules are torsion-free but not locally free on the double
locus.  The plural statement in Remark 1.3, PDF page 5, must be
qualified by degree: $\Omega^2_{X/B}$ does have torsion on the cusp
double locus.  The workbench's degree-one correction is correct;
it must not be extended to degree two.
\end{claim}

\begin{claim}{B1.0}{Proved}{The marked geometric dictionary on the first page}
The lattice matrix, meridian orientations, line bundle and parameter
comparison stated on the first page identify the two marked smooth
families. The ambiguity in $u$ is exactly multiplication by the
nonzero constant specifying Engel's reference linearization.
\end{claim}

\begin{claim}{C2.1}{Proved}{Bott--Chern and Aeppli tables as functions of $h$}
With
\[
H^{p,q}_{BC}=
\frac{\ker\partial\cap\ker\bar\partial\subset A^{p,q}}
{\im\partial\bar\partial},\qquad
H^{p,q}_{A}=
\frac{\ker\partial\bar\partial\subset A^{p,q}}
{\im\partial+\im\bar\partial},
\]
the complete tables are
\begin{equation}\label{eq:C-BC-A}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&1&1\\
2&0&h&2h&1\\
1&0&2&h&0\\
0&1&0&0&0
\end{array}_{BC}
\qquad
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&2&0\\
1&1&2h&h&0\\
0&1&1&0&0.
\end{array}_{A}
\end{equation}
In particular, substitution of the value $h=1$ proved in A3.1 gives
the workbench's numerical tables.  The totals are
$(1,0,2,2,2,2,1)$ and $(1,2,2,2,2,0,1)$, respectively.
\end{claim}

\begin{claim}{C2.2}{Proved}{Comparison with McHugh and Angella}
The specialization of McHugh's Theorem 6.3, Proposition 6.4, equation
(7), and Section 7.1 to \eqref{eq:C-hodge-input} agrees with C2.1.
The corresponding relations and Figure 5 in Angella's Section 4 also
agree.  No correction to these specific formulas is required.
\end{claim}

\begin{claim}{C3.2}{Proved}{The factor $12$ with a fixed collar orientation}
Use the marked cohomology class $\gamma$ dual to
$\hat\gamma$, the clockwise meridians and the lift relation of
[AC26, Section 7.5], and put
$p=12l_0-4l_1-3l_2=\pm1$.  Let $g_\gamma$ be the unique coherent
Leray class whose fibre image is $\gamma^{0,1}$.  Then
\begin{equation}\label{eq:C-factor12}
\exp(12g_\gamma)=f^*\OO_{\Pone}(-p).
\end{equation}
For the standard data $(l_0,l_1,l_2)=(0,1,-1)$, this is
$\exp(12g_\gamma)=f^*\OO(1)$.  For the opposite value $p=1$,
the exponent representing $f^*\OO(1)$ is $-12g_\gamma$.
\end{claim}

\begin{claim}{C3.4}{Proved}{Non-K\"ahler degrees and the precise degreewise statement}
For $k=0,\ldots,6$ the non-K\"ahler degrees are
\begin{equation}\label{eq:C-delta}
(\Delta^k)=(0,2,2+2h,4h,2+2h,2,0).
\end{equation}
If $h\ge1$, the two maps
$\bigoplus_{p+q=k}H^{p,q}_{BC}\to H^k_{\mathrm{dR}}(X;\C)
\to\bigoplus_{p+q=k}H^{p,q}_A$
are both isomorphisms exactly for $k=0,6$.
For the weaker assertion that a $d$-exact pure $d$-closed form of
degree $k$ is $\partial\bar\partial$-exact, the valid degrees are
$k=0,1,6$, and also $k=3,4$ if $h=0$.
\end{claim}

\begin{claim}{C3.5}{Proved}{Metric obstructions that do not require $h$}
The threefold $X$ admits no balanced, strongly Gauduchon, K\"ahler,
locally conformally K\"ahler, or Hermitian-symplectic metric.
\end{claim}

\begin{claim}{C3.6}{Known}{Gauduchon metrics with specified Chern--Ricci form}
There exists a Gauduchon metric on $X$.  More precisely, for every
Gauduchon metric $\omega_0$ there is another Gauduchon metric
$\omega$ with $[\omega^2]_A=[\omega_0^2]_A$ and
\begin{equation}\label{eq:C-Ricci}
\operatorname{Ric}^{\mathrm{Ch}}(\omega)=\pi f^*\omega_{FS}.
\end{equation}
This Ricci form is semipositive and has rank one at regular points
of $f$.  No Chern--Ricci-flat Hermitian metric exists on $X$.
\end{claim}

\begin{claim}{D1.3}{Proved}{The untwisted tangent direct images}
For every admissible $c$ in the standard family,
\[
 \boxed{f_*T_X=\OO\oplus\OO(-1),\quad
 R^1f_*T_X=\OO\oplus\OO(-1)^2,\quad R^2f_*T_X=\OO.}   \tag{D.4}
\]
Consequently $(h^0,h^1,h^2,h^3)(X,T_X)=(1,1,1,0)$.
\end{claim}

\begin{claim}{D2.1}{Proved}{The entire first tangent cohomology}
The Leray class $\xi\otimes[\gamma]$ generates $H^1(X,T_X)$.
The Kodaira--Spencer map of $c\mapsto X_c$ is an isomorphism
$T_c\mathcal P\to H^1(X_c,T_{X_c})$ at every admissible $c$.
\end{claim}

\begin{claim}{D3.1}{Proved}{The obstruction map and the Kuranishi germ}
The primary Kuranishi bracket is zero, the Kuranishi germ of $X_c$ is
a smooth one-dimensional germ, and the $c$-family is locally
semiuniversal. The equality $h^2(T_X)=h^1(T_X)=1$ does not identify the
nonzero obstruction space with a nonzero obstruction map.
\end{claim}

\begin{statement}[C.1.2; Proved: the phases and the two periods]
With the branch continued from the specified cusp, the exact values are
\begin{align*}
 \frac{\vartheta _1((2-\rho)/3,\rho)}{\eta(\rho)}
   &=e^{\pi i/12}\,3^{1/4}e^{\pi/(6\sqrt3)},\\
 \frac{\vartheta _1((1-i)/2,i)}{\eta(i)}
   &=\sqrt2\,e^{\pi/4},\\
 \beta^{\rm part}(z_1)
   &=-\frac12+i\left(\frac1{\sqrt3}-\frac3{2\pi}\log48\right),\\
 \beta^{\rm part}(z_2)
   &=i\left(\frac32-\frac3\pi\log6\right).
\end{align*}
Consequently $N(z_1)=3^{1/4}$, $N(z_2)=\sqrt2$,
$D_{\rm part}(z_1)=-3\log48/(2\pi)$, and
$D_{\rm part}(z_2)=-3\log6/\pi$.
\end{statement}

\begin{statement}[C.4.2; Proved: the full division identity]
Let $\psi_m$ be the standard division polynomial of a smooth
Weierstrass model, normalized by $\psi_1=1$, $\psi_2=2y$.
For $m\ge2$ and $Q,mQ\ne O$,
\begin{equation}\label{eq:cs-division}
 N(Q)^{m^2}
       =N(mQ)\frac{|\Delta_E|^{(m^2-1)/12}}{|\psi_m(Q)|}.
\end{equation}
For the displayed family this specializes to
\[
 N(P)^4=3^{3/4}|t-1|^{-1/4}N(2P),\qquad
 N(P)^9=16|t|^{-2/3}N(3P).
\]
If $P_t$ has exact order $n$ and $m\ge2$ satisfies
$m\equiv1$ or $-1\pmod n$, then
\begin{equation}\label{eq:cs-torsionvalue}
 N(P_t)^{12}
       =\frac{|\Delta(t)|}{|\psi_m(P_t)|^{12/(m^2-1)}}.
\end{equation}
The positive value on the right is independent of $m$.
\end{statement}

\begin{statement}[C.6.2; Proved: exact finite local-height calculation]
Let $E/\Q$ be a global minimal Weierstrass model. If $mP$ is
in the identity component at $p$, and $mP\ne O$, then
\begin{equation}\label{eq:ch-local-exact}
 \frac{\lambda_p(P)}{\log p}
 =\frac{v_p(\Delta)}{12}
   +\frac{\frac12\max(0,-v_p(x(mP)))-v_p(\psi_m(P))}{m^2}.
\end{equation}
For $m=1$ we read $\psi_1=1$. This formula, with exact rational
coordinates and valuations, gives all the finite contributions
in the tables below.
\end{statement}

\begin{statement}[C.8.9; Refuted sign and normalization, with the corrected current identity proved]
On a local period chart write $\mu=a\tau+b$, with $a,b$ real,
and put $T=\Im\tau$. The positive Betti measure is
\[
 m_P=db\wedge da
 =\frac{|\mu_w-a\tau_w|^2}{T}\,dA_w.
\]
Thus the form $da\wedge db$ in Lead 15(b) has the wrong sign.
The globally single-valued function $L(t)=\log N(P_t)$ satisfies
on $\mathbb P^1(\C)$
\begin{equation}\label{eq:ca-current}
 dd^cL=\frac1{12}\delta_\infty-m_P,\qquad
               \int_{\mathbb P^1}m_P=\frac1{12}.
\end{equation}
There are no atoms of $m_P$ at $0$, $1$ or $\infty$.
Let $T_0=\sqrt3/2$, $\rho=(1+i\sqrt3)/2$, and
$p=\wp'_\rho((2-\rho)/3)$. The density in the ordinary
$t$ coordinate satisfies
\begin{align}
 \frac{dm_P}{dA_t}
 &=\frac{|t|^{-2/3}}{64T_0|p|^{2/3}}
                      \bigl(1+O(|t|^{1/3})\bigr),
                         &&t\longrightarrow0,\label{eq:ca-density0}\\
 \frac{dm_P}{dA_t}
 &=\frac{|t-1|^{-3/2}}{24\pi^2\sqrt{E_4(i)}}
                      \bigl(1+O(|t-1|^{1/2})\bigr),
                         &&t\longrightarrow1.\label{eq:ca-density1}
\end{align}
\end{statement}

\begin{statement}[C.8.13; Proved: the cusp exclusion]
If $\Im\tau\ge7/5$, then $|F|<17/20$.
\end{statement}
